// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./MyToken.sol";

contract R2RMiningPool is Ownable {
    RelaxCoin public immutable r2rToken;
    uint256 public totalShares;
    uint256 public accRewardPerShare;
    uint256 public pendingRewardPool;
    uint256 public targetBase = type(uint256).max / 1024;
    uint256 public constant ACC_FACTOR = 1e18;
    bool public paused;
    address public timelock;
    uint256 public rewardRate;
    uint256 public miningDifficulty = 1000000;

    struct Miner {
        uint256 shares;
        uint256 rewardDebt;
        uint256 pendingRewards;
    }

    mapping(address => Miner) public miners;

    event ShareSubmitted(address indexed miner, uint256 difficulty, bytes32 challenge);
    event RewardsDistributed(uint256 amount, uint256 accRewardPerShare);
    event RewardsClaimed(address indexed miner, uint256 amount);
    event TargetBaseUpdated(uint256 previousTarget, uint256 newTarget);

    modifier whenNotPaused() {
        require(!paused, "R2RMiningPool: paused");
        _;
    }

    modifier onlyAdmin() {
        require(msg.sender == owner() || msg.sender == timelock, "R2RMiningPool: not admin");
        _;
    }

    constructor(RelaxCoin _r2rToken) Ownable(msg.sender) {
        require(address(_r2rToken) != address(0), "R2RMiningPool: token zero");
        r2rToken = _r2rToken;
    }

    function setTimelock(address _timelock) external onlyOwner {
        require(_timelock != address(0), "R2RMiningPool: timelock zero");
        timelock = _timelock;
    }

    function pause() external onlyAdmin {
        paused = true;
    }

    function unpause() external onlyAdmin {
        paused = false;
    }

    function emergencyWithdraw(address to, uint256 amount) external onlyAdmin {
        require(to != address(0), "R2RMiningPool: to zero");
        require(r2rToken.transfer(to, amount), "R2RMiningPool: transfer failed");
    }

    function setTargetBase(uint256 newTargetBase) external onlyOwner {
        require(newTargetBase > 0, "R2RMiningPool: target base zero");
        emit TargetBaseUpdated(targetBase, newTargetBase);
        targetBase = newTargetBase;
    }

    function setRewardRate(uint256 newRate) external onlyAdmin {
        rewardRate = newRate;
    }

    function setMiningDifficulty(uint256 newDifficulty) external onlyAdmin {
        require(newDifficulty > 0, "R2RMiningPool: difficulty zero");
        miningDifficulty = newDifficulty;
    }

    function submitShare(uint256 nonce, uint256 difficulty) external whenNotPaused returns (bool) {
        require(difficulty > 0 && difficulty <= miningDifficulty, "R2RMiningPool: invalid difficulty");
        bytes32 challenge = keccak256(abi.encodePacked(blockhash(block.number - 1), msg.sender, nonce, difficulty));
        uint256 target = targetBase / difficulty;
        require(uint256(challenge) < target, "R2RMiningPool: invalid share");

        _updateMiner(msg.sender);

        uint256 shareValue = difficulty;
        miners[msg.sender].shares += shareValue;
        totalShares += shareValue;

        if (pendingRewardPool > 0) {
            accRewardPerShare += (pendingRewardPool * ACC_FACTOR) / totalShares;
            pendingRewardPool = 0;
        }

        miners[msg.sender].rewardDebt = (miners[msg.sender].shares * accRewardPerShare) / ACC_FACTOR;

        emit ShareSubmitted(msg.sender, difficulty, challenge);
        return true;
    }

    function distributeRewards(uint256 amount) external onlyOwner {
        require(amount > 0, "R2RMiningPool: amount zero");

        r2rToken.mintForMining(address(this), amount);

        if (totalShares == 0) {
            pendingRewardPool += amount;
            emit RewardsDistributed(amount, accRewardPerShare);
            return;
        }

        accRewardPerShare += (amount * ACC_FACTOR) / totalShares;

        emit RewardsDistributed(amount, accRewardPerShare);
    }

    function claimRewards() external {
        _updateMiner(msg.sender);

        uint256 reward = miners[msg.sender].pendingRewards;
        require(reward > 0, "R2RMiningPool: no reward");

        miners[msg.sender].pendingRewards = 0;
        require(r2rToken.transfer(msg.sender, reward), "R2RMiningPool: transfer failed");

        emit RewardsClaimed(msg.sender, reward);
    }

    function pendingReward(address miner) external view returns (uint256) {
        uint256 accumulated = (miners[miner].shares * accRewardPerShare) / ACC_FACTOR;
        if (accumulated <= miners[miner].rewardDebt) {
            return miners[miner].pendingRewards;
        }
        return miners[miner].pendingRewards + (accumulated - miners[miner].rewardDebt);
    }

    function _updateMiner(address miner) internal {
        uint256 accumulated = (miners[miner].shares * accRewardPerShare) / ACC_FACTOR;
        if (accumulated > miners[miner].rewardDebt) {
            miners[miner].pendingRewards += accumulated - miners[miner].rewardDebt;
        }
        miners[miner].rewardDebt = accumulated;
    }
}

contracts/R2RStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

interface IRelaxCoin {
    function purchaseTransfer(address from, address to, uint256 amount) external returns (bool);
    function systemTransfer(address to, uint256 amount) external returns (bool);
}

contract R2RStaking is Ownable {
    IRelaxCoin public immutable r2rToken;

    struct Tier {
        uint256 minStake;
        uint256 industryTaxPercent;
        string label;
    }

    Tier[] public tiers;
    mapping(address => uint256) public staked;
    uint256 public totalStaked;

    event Staked(address indexed account, uint256 amount);
    event Unstaked(address indexed account, uint256 amount);
    event TierUpdated(uint256 index, uint256 minStake, uint256 industryTaxPercent, string label);

    constructor(address _r2rToken) Ownable(msg.sender) {
        require(_r2rToken != address(0), "R2RStaking: token zero");
        r2rToken = IRelaxCoin(_r2rToken);

        tiers.push(Tier({minStake: 5000000 * 10 ** 18, industryTaxPercent: 900, label: "Bronze"}));
        tiers.push(Tier({minStake: 20000000 * 10 ** 18, industryTaxPercent: 600, label: "Silver"}));
        tiers.push(Tier({minStake: 50000000 * 10 ** 18, industryTaxPercent: 250, label: "Gold"}));
    }

    function stake(uint256 amount) external {
        require(amount > 0, "R2RStaking: amount zero");
        staked[msg.sender] += amount;
        totalStaked += amount;
        require(r2rToken.purchaseTransfer(msg.sender, address(this), amount), "R2RStaking: transfer failed");
        emit Staked(msg.sender, amount);
    }

    function unstake(uint256 amount) external {
        require(amount > 0, "R2RStaking: amount zero");
        require(staked[msg.sender] >= amount, "R2RStaking: insufficient stake");
        staked[msg.sender] -= amount;
        totalStaked -= amount;
        require(r2rToken.systemTransfer(msg.sender, amount), "R2RStaking: transfer failed");
        emit Unstaked(msg.sender, amount);
    }

    function industryTaxPercentFor(address account) external view returns (uint256) {
        uint256 balance = staked[account];
        for (uint256 i = tiers.length; i > 0; ) {
            unchecked { i--; }
            if (balance >= tiers[i].minStake) {
                return tiers[i].industryTaxPercent;
            }
        }
        return 1050;
    }

    function tierFor(address account) external view returns (string memory) {
        uint256 balance = staked[account];
        for (uint256 i = tiers.length; i > 0; ) {
            unchecked { i--; }
            if (balance >= tiers[i].minStake) {
                return tiers[i].label;
            }
        }
        return "None";
    }

    function updateTier(uint256 index, uint256 minStake, uint256 industryTaxPercent, string calldata label) external onlyOwner {
        require(index < tiers.length, "R2RStaking: invalid tier");
        tiers[index] = Tier({minStake: minStake, industryTaxPercent: industryTaxPercent, label: label});
        emit TierUpdated(index, minStake, industryTaxPercent, label);
    }
}

contracts/R2RTokenFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IR2RBonusCoin {
    function balanceOf(address account) external view returns (uint256);
    function purchaseTransfer(address from, address to, uint256 amount) external returns (bool);
    function systemTransfer(address to, uint256 amount) external returns (bool);
}

interface IR2RStakeView {
    function staked(address account) external view returns (uint256);
}

interface IR2RTokenFactoryRewards {
    function quoteCreatorBonus(address token, address creator, uint256 platformFeeAmount) external view returns (uint256);
    function payCreatorBonus(address token, address creator, uint256 platformFeeAmount) external returns (uint256);
}

contract R2RCreatedToken is ERC20 {
    uint256 public constant RECIPIENT_BPS = 7000;
    uint256 public constant CREATOR_BPS = 2100;
    uint256 public constant BPS = 10000;

    address public immutable creator;
    address public immutable feeRecipient;
    IR2RTokenFactoryRewards public immutable factory;

    event PaymentProcessed(
        address indexed sender,
        address indexed recipient,
        uint256 amount,
        uint256 recipientAmount,
        uint256 creatorAmount,
        uint256 platformAmount,
        uint256 r2rBonus
    );

    constructor(
        string memory name_,
        string memory symbol_,
        uint256 creatorSupply,
        uint256 feeSupply,
        address creator_,
        address feeRecipient_,
        address factory_
    ) ERC20(name_, symbol_) {
        require(creator_ != address(0), "R2RToken: creator zero");
        require(feeRecipient_ != address(0), "R2RToken: fee recipient zero");
        require(factory_ != address(0), "R2RToken: factory zero");
        creator = creator_;
        feeRecipient = feeRecipient_;
        factory = IR2RTokenFactoryRewards(factory_);
        _mint(creator_, creatorSupply);
        _mint(feeRecipient_, feeSupply);
    }

    function pay(address recipient, uint256 amount) external returns (bool) {
        require(amount > 0, "R2RToken: amount zero");
        _transfer(_msgSender(), recipient, amount);
        return true;
    }

    function previewTransfer(uint256 amount)
        external
        view
        returns (uint256 recipientAmount, uint256 creatorAmount, uint256 platformAmount, uint256 r2rBonus)
    {
        recipientAmount = Math.mulDiv(amount, RECIPIENT_BPS, BPS);
        creatorAmount = Math.mulDiv(amount, CREATOR_BPS, BPS);
        platformAmount = amount - recipientAmount - creatorAmount;
        r2rBonus = factory.quoteCreatorBonus(address(this), creator, platformAmount);
    }

    function _update(address from, address to, uint256 amount) internal override {
        if (from == address(0) || to == address(0)) {
            super._update(from, to, amount);
            return;
        }

        uint256 recipientAmount = Math.mulDiv(amount, RECIPIENT_BPS, BPS);
        uint256 creatorAmount = Math.mulDiv(amount, CREATOR_BPS, BPS);
        uint256 platformAmount = amount - recipientAmount - creatorAmount;

        super._update(from, to, recipientAmount);
        if (creatorAmount > 0) super._update(from, creator, creatorAmount);
        if (platformAmount > 0) super._update(from, feeRecipient, platformAmount);

        uint256 r2rBonus;
        if (platformAmount > 0) {
            r2rBonus = factory.payCreatorBonus(address(this), creator, platformAmount);
        }
        emit PaymentProcessed(from, to, amount, recipientAmount, creatorAmount, platformAmount, r2rBonus);
    }
}

contract R2RTokenFactory is Ownable, ReentrancyGuard {
    using Math for uint256;

    uint256 public constant COMMISSION_BPS = 3000;
    uint256 public constant BPS = 10000;
    uint256 private constant TOKEN_UNIT = 1e18;

    address public feeRecipient;
    IR2RBonusCoin public immutable r2rToken;
    IR2RStakeView public immutable stakingContract;
    mapping(address => bool) public isCreatedToken;
    mapping(address => uint256) public tokenR2RRateE18;

    event TokenCreated(address indexed creator, address indexed token, string name, string symbol, uint256 supply, uint256 commission);
    event FeeRecipientUpdated(address indexed previousRecipient, address indexed newRecipient);
    event TokenR2RRateUpdated(address indexed token, uint256 previousRateE18, uint256 newRateE18);
    event BonusPoolFunded(address indexed funder, uint256 amount, uint256 newBalance);
    event BonusPoolWithdrawn(address indexed recipient, uint256 amount, uint256 newBalance);
    event CreatorBonusPaid(address indexed token, address indexed creator, uint256 platformFeeAmount, uint256 r2rAmount, uint256 rateBps);

    constructor(address initialOwner, address initialFeeRecipient, address r2rToken_, address stakingContract_)
        Ownable(initialOwner)
    {
        require(initialFeeRecipient != address(0), "R2RFactory: recipient zero");
        require(r2rToken_ != address(0), "R2RFactory: R2R token zero");
        require(stakingContract_ != address(0), "R2RFactory: staking zero");
        feeRecipient = initialFeeRecipient;
        r2rToken = IR2RBonusCoin(r2rToken_);
        stakingContract = IR2RStakeView(stakingContract_);
    }

    function setFeeRecipient(address newRecipient) external onlyOwner {
        require(newRecipient != address(0), "R2RFactory: recipient zero");
        emit FeeRecipientUpdated(feeRecipient, newRecipient);
        feeRecipient = newRecipient;
    }

    function setTokenR2RRate(address token, uint256 rateE18) external onlyOwner {
        require(isCreatedToken[token], "R2RFactory: unknown token");
        require(rateE18 > 0, "R2RFactory: rate zero");
        uint256 previousRate = tokenR2RRateE18[token];
        tokenR2RRateE18[token] = rateE18;
        emit TokenR2RRateUpdated(token, previousRate, rateE18);
    }

    function fundBonusPool(uint256 amount) external nonReentrant {
        require(amount > 0, "R2RFactory: amount zero");
        require(r2rToken.purchaseTransfer(msg.sender, address(this), amount), "R2RFactory: funding failed");
        emit BonusPoolFunded(msg.sender, amount, bonusPoolBalance());
    }

    function withdrawBonusPool(address recipient, uint256 amount) external onlyOwner nonReentrant {
        require(recipient != address(0), "R2RFactory: recipient zero");
        require(amount > 0, "R2RFactory: amount zero");
        require(r2rToken.systemTransfer(recipient, amount), "R2RFactory: withdrawal failed");
        emit BonusPoolWithdrawn(recipient, amount, bonusPoolBalance());
    }

    function bonusPoolBalance() public view returns (uint256) {
        return r2rToken.balanceOf(address(this));
    }

    function creatorBonusBpsFor(address creator) public view returns (uint256) {
        uint256 stakeAmount = stakingContract.staked(creator);
        if (stakeAmount >= 5000 * TOKEN_UNIT) return 1400;
        if (stakeAmount >= 1000 * TOKEN_UNIT) return 1100;
        if (stakeAmount >= 500 * TOKEN_UNIT) return 800;
        if (stakeAmount >= 100 * TOKEN_UNIT) return 500;
        return 300;
    }

    function quoteCreatorBonus(address token, address creator, uint256 platformFeeAmount) public view returns (uint256) {
        uint256 rate = tokenR2RRateE18[token];
        if (!isCreatedToken[token] || rate == 0 || platformFeeAmount == 0) return 0;
        uint256 r2rValue = Math.mulDiv(platformFeeAmount, rate, TOKEN_UNIT);
        return Math.mulDiv(r2rValue, creatorBonusBpsFor(creator), BPS);
    }

    function payCreatorBonus(address token, address creator, uint256 platformFeeAmount)
        external
        nonReentrant
        returns (uint256 bonusAmount)
    {
        require(isCreatedToken[token], "R2RFactory: unknown token");
        require(msg.sender == token, "R2RFactory: caller is not token");
        require(tokenR2RRateE18[token] > 0, "R2RFactory: token rate not set");

        bonusAmount = quoteCreatorBonus(token, creator, platformFeeAmount);
        if (bonusAmount == 0) return 0;
        require(bonusPoolBalance() >= bonusAmount, "R2RFactory: insufficient R2R bonus pool");
        require(r2rToken.systemTransfer(creator, bonusAmount), "R2RFactory: bonus payment failed");
        emit CreatorBonusPaid(token, creator, platformFeeAmount, bonusAmount, creatorBonusBpsFor(creator));
    }

    function createToken(string calldata name_, string calldata symbol_, uint256 supply) external returns (address tokenAddress) {
        require(bytes(name_).length > 0 && bytes(name_).length <= 64, "R2RFactory: invalid name");
        require(bytes(symbol_).length > 0 && bytes(symbol_).length <= 12, "R2RFactory: invalid symbol");
        require(supply > 0, "R2RFactory: supply zero");

        uint256 commission = (supply / BPS) * COMMISSION_BPS
            + ((supply % BPS) * COMMISSION_BPS) / BPS;
        uint256 creatorSupply = supply - commission;
        R2RCreatedToken token = new R2RCreatedToken(
            name_,
            symbol_,
            creatorSupply,
            commission,
            msg.sender,
            feeRecipient,
            address(this)
        );
        tokenAddress = address(token);
        isCreatedToken[tokenAddress] = true;
        emit TokenCreated(msg.sender, tokenAddress, name_, symbol_, supply, commission);
    }
}

contracts/R2RUSD.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract R2RUSD is ERC20, Ownable {
    address public minter;

    event MinterUpdated(address indexed previousMinter, address indexed newMinter);

    constructor(address _minter) ERC20("RelaxCoin USD", "R2RUSD") Ownable(msg.sender) {
        require(_minter != address(0), "R2RUSD: minter zero");
        minter = _minter;
    }

    modifier onlyMinter() {
        require(msg.sender == minter, "R2RUSD: caller is not minter");
        _;
    }

    function setMinter(address newMinter) external onlyOwner {
        require(newMinter != address(0), "R2RUSD: minter zero");
        emit MinterUpdated(minter, newMinter);
        minter = newMinter;
    }

    function mint(address to, uint256 amount) external onlyMinter {
        _mint(to, amount);
    }

    function burn(address from, uint256 amount) external onlyMinter {
        _burn(from, amount);
    }
}

contracts/R2RVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./MyToken.sol";
import "./R2RUSD.sol";

contract R2RVault is Ownable {
    using SafeERC20 for IERC20;

    RelaxCoin public immutable r2rToken;
    R2RUSD public immutable stablecoin;

    uint256 public industryMarketCapUsd;
    uint256 public r2rUsdPrice;
    uint256 public totalCollateralR2R;
    uint256 public totalStableMinted;

    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant TARGET_RATIO = 1100;

    mapping(address => uint256) public collateralBalance;

    event CollateralDeposited(address indexed account, uint256 amountR2R);
    event CollateralWithdrawn(address indexed account, uint256 amountR2R);
    event IndustryMarketCapUpdated(uint256 previousCap, uint256 newCap);
    event R2RPriceUpdated(uint256 previousPrice, uint256 newPrice);
    event StableMinted(address indexed to, uint256 amountUsd);
    event StableBurned(address indexed from, uint256 amountUsd);

    constructor(RelaxCoin _r2rToken, R2RUSD _stablecoin, uint256 _initialR2RUsdPrice) Ownable(msg.sender) {
        require(address(_r2rToken) != address(0), "R2RVault: r2r zero");
        require(address(_stablecoin) != address(0), "R2RVault: stablecoin zero");
        require(_initialR2RUsdPrice > 0, "R2RVault: price zero");

        r2rToken = _r2rToken;
        stablecoin = _stablecoin;
        r2rUsdPrice = _initialR2RUsdPrice;
    }

    function depositR2R(uint256 amount) external {
        require(amount > 0, "R2RVault: amount zero");
        r2rToken.transferFrom(msg.sender, address(this), amount);
        totalCollateralR2R += amount;
        collateralBalance[msg.sender] += amount;
        emit CollateralDeposited(msg.sender, amount);
    }

    function withdrawR2R(uint256 amount) external {
        require(amount > 0, "R2RVault: amount zero");
        require(collateralBalance[msg.sender] >= amount, "R2RVault: insufficient collateral");
        require(totalCollateralR2R - amount >= minCollateralRequired(), "R2RVault: insufficient backed collateral");

        collateralBalance[msg.sender] -= amount;
        totalCollateralR2R -= amount;
        r2rToken.transfer(msg.sender, amount);
        emit CollateralWithdrawn(msg.sender, amount);
    }

    function updateIndustryMarketCapUsd(uint256 newCapUsd) external onlyOwner {
        emit IndustryMarketCapUpdated(industryMarketCapUsd, newCapUsd);
        industryMarketCapUsd = newCapUsd;
    }

    function updateR2RPrice(uint256 newPriceUsd) external onlyOwner {
        require(newPriceUsd > 0, "R2RVault: price zero");
        emit R2RPriceUpdated(r2rUsdPrice, newPriceUsd);
        r2rUsdPrice = newPriceUsd;
    }

    function targetPoolUsd() public view returns (uint256) {
        return (industryMarketCapUsd * TARGET_RATIO) / BASIS_POINTS;
    }

    function collateralValueUsd() public view returns (uint256) {
        return (totalCollateralR2R * r2rUsdPrice) / 1e18;
    }

    function minCollateralRequired() public view returns (uint256) {
        return totalStableMinted == 0 ? 0 : (totalStableMinted * 1e18 + r2rUsdPrice - 1) / r2rUsdPrice;
    }

    function mintStable(address to, uint256 amountUsd) external onlyOwner {
        require(amountUsd > 0, "R2RVault: amount zero");
        require(totalStableMinted + amountUsd <= targetPoolUsd(), "R2RVault: target pool exceeded");
        require(collateralValueUsd() >= totalStableMinted + amountUsd, "R2RVault: insufficient collateral value");

        totalStableMinted += amountUsd;
        stablecoin.mint(to, amountUsd);
        emit StableMinted(to, amountUsd);
    }

    function burnStable(address from, uint256 amountUsd) external onlyOwner {
        require(amountUsd > 0, "R2RVault: amount zero");
        totalStableMinted -= amountUsd;
        stablecoin.burn(from, amountUsd);
        emit StableBurned(from, amountUsd);
    }
}

